// YCT Admin Panel Worker
// Serves the admin panel at crimson-art-feea.yct-app.workers.dev

const HTML_B64 = "";

function decodeHTML() {
  const binary = atob(HTML_B64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new TextDecoder('utf-8').decode(bytes);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === '/' || url.pathname === '') {
      return new Response(decodeHTML(), {
        headers: { 'Content-Type': 'text/html;charset=UTF-8' }
      });
    }
    // R2 upload proxy
    if (url.pathname === '/upload' && request.method === 'POST') {
      try {
        const form = await request.formData();
        const file = form.get('file');
        const path = form.get('path');
        if (!file || !path) return new Response(JSON.stringify({error:'Missing file or path'}), {status:400,headers:{'Content-Type':'application/json'}});
        await env.YCT_BUCKET.put(path, file.stream(), {
          httpMetadata: { contentType: file.type || 'application/octet-stream' }
        });
        const url2 = `https://pub-360b7b3324fb4f22bb35e656f476062a.r2.dev/${path}`;
        return new Response(JSON.stringify({url: url2}), {headers:{'Content-Type':'application/json'}});
      } catch(e) {
        return new Response(JSON.stringify({error:e.message}), {status:500,headers:{'Content-Type':'application/json'}});
      }
    }
    // R2 delete proxy
    if (url.pathname === '/delete' && request.method === 'DELETE') {
      try {
        const body = await request.json();
        if (body.path) await env.YCT_BUCKET.delete(body.path);
        return new Response(JSON.stringify({ok:true}), {headers:{'Content-Type':'application/json'}});
      } catch(e) {
        return new Response(JSON.stringify({error:e.message}), {status:500,headers:{'Content-Type':'application/json'}});
      }
    }
    return new Response('Not found', {status:404});
  }
};
